sql.where:
w.del_flag = '0'
 and w.id = #{id}
 and w.supplier_name like concat('%', #{unitName}, '%')
 and w.supplier_name like concat('%', #{supplierName}, '%')
 and concat('供应商提现申请-', w.withdraw_no) like concat('%', #{projectName}, '%')
 and date_format(coalesce(w.apply_time, w.create_time), '%Y-%m') = #{settlementCycle}

    and case
        when w.status = '3' then '2'
        when w.status in ('2', '4') then '1'
        else '0'
    end = #{status}

 and ff.dept_id = #{deptId}

    and exists (
        select 1
        from xfpt_school_supplier_rel sr
        where sr.school_id = #{params.schoolId}
          and sr.supplier_id = w.supplier_id
          and sr.cooperate_status = '1'
          and sr.del_flag = 0
    )
